/**
 * GENERATED by scripts/fork-cosigner.mjs from vendor/agent/src/roles/cosigner.ts (the release's co-signer, which
 * stays unmodified). Do not edit by hand: change the script and run it again; test/cosigner-fork.test.ts checks that
 * this file is exactly the script's output and that, for an ordinary-key owner on a 6-decimal vault, the fork and the
 * release engine certify or refuse identically (with every check the same except the three change 5 redefines).
 *
 * Decision D-A (22 Nov 2026, taken by the R7 orchestrator, not by the owner; docs/r7/00-ARCHITECTURE-DECISIONS.md).
 * Two changes, nothing else:
 *   1. owner signatures (C1 mandate, C3 instruction, conversion and policy) are checked as the vault checks them:
 *      ECDSA recovery for an owner without code (exactly the release's check), ERC-1271 isValidSignature for a
 *      contract owner (a workspace's passkey account, chain/accounts);
 *   2. the reserve buffer (5 units), the earned-autonomy base (10 units) and the amounts written in records use the
 *      decimals of the vault's own asset, read from the chain.
 * Decision D-K4a (R13, F-018), for every configuration:
 *   5. each named check of a conversion can fail alone: P2 is "if a tranche is due, the request is no larger than the
 *      tranche the policy allows (shortfall, caps, free funds) and no smaller than its smallest", the cost limit being P3's
 *      alone; T2 is computed only when T1 passes; T3 recomputes the venue-set hash from the venues read and compares.
 * R7 decision D7 (docs/r7/00-ARCHITECTURE-DECISIONS.md D7; experiments/r7/S1-science/D7-authority-budget.md), only
 * when the configuration says authority "d7":
 *   3. check C12 is the authority budget (rail/authority-ledger.ts): a payment's C12 keeps its id and place; a
 *      conversion gains C12 as its last check; certificates signed and not yet used reserve their worst case; K1's caps
 *      on earned authority are the operator's, lowered by the owner's passkey-signed caps in force (D-K1b);
 *   4. a conversion's certificate expires after 15 minutes instead of 4 hours, so the worst case a reverted
 *      conversion reserved is released within minutes (experiments/r8/D7-validation, F-R8-4).
 * Money-model S5, only when the configuration sets minToleranceUnits (a workspace whose currency set is not the default):
 *   6. an order's τ never asks for less than that many base units of the output token, and never more than 1%.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { encodeAbiParameters, getAddress, hashMessage, keccak256, recoverAddress, recoverMessageAddress, toHex, type Address, type Hex, type LocalAccount } from "viem";
import type { Vendored } from "./vendored.ts";
import type { CertRequest, CertResponse, CosignerConfig, TradeRequest, TradeResponse } from "../vendor/agent/src/roles/cosigner.ts";
import type { Chain$ } from "../vendor/agent/src/chain.ts";
import type { Certificate } from "../vendor/agent/src/protocol/eip712.ts";
import type { Check } from "../vendor/agent/src/engine/economics.ts";
import type { Order } from "../vendor/agent/src/roles/trader.ts";
import type { AuthorityView } from "../types.ts";
import { bandOf, buildLedger, conversionCost, eventsFromLogs, paymentCost, price, readAuthorityLogs, units, viewOf, withOwnerCaps, type D7Config, type Grant, type Ledger, type Reservation } from "./authority-ledger.ts";

/** The engine's configuration: the release's, and the authority rule (R7 D7). Without an authority rule, or with "release", C12 is the release's. */
export type ForkCosignerConfig = CosignerConfig & { authority?: "release" | "d7"; d7?: D7Config; minToleranceUnits?: number };

const ERC1271_ABI = [{ type: "function", name: "isValidSignature", stateMutability: "view", inputs: [{ name: "hash", type: "bytes32" }, { name: "signature", type: "bytes" }], outputs: [{ name: "", type: "bytes4" }] }] as const;
const ERC20_DECIMALS_ABI = [{ type: "function", name: "decimals", stateMutability: "view", inputs: [], outputs: [{ name: "", type: "uint8" }] }] as const;
const VAULT_ASSET_ABI = [{ type: "function", name: "asset", stateMutability: "view", inputs: [], outputs: [{ name: "", type: "address" }] }] as const;
/** R7 D7 (change 4): how long a conversion's certificate, and so the reservation of its worst case, lives. */
export const D7_CONVERSION_CERTIFICATE_SECONDS = 15 * 60;
/** D-K4a (change 5): QEDExecution's venue-set hash, keccak256(abi.encode(Venue[])), recomputed from venues as read. */
export function venueSetHashOf(venues: readonly { pool: Address; token0: Address; token1: Address; feeBps: number }[]): Hex {
  return keccak256(encodeAbiParameters([{ type: "tuple[]", components: [{ name: "pool", type: "address" }, { name: "token0", type: "address" }, { name: "token1", type: "address" }, { name: "feeBps", type: "uint16" }] }], [venues.map((v) => ({ pool: v.pool, token0: v.token0, token1: v.token1, feeBps: v.feeBps }))]));
}
/**
 * D-K4a (change 5): the tranche the policy allows before its cost limit: the release's decideTranche candidates without
 * "impact", in the release's own order (the shortfall's tranche when the caps can cover it, else the caps alone).
 */
export function policyTranche(c: { need: bigint | null; policyCap: bigint; mandateCap: bigint; freeFunds: bigint }): bigint {
  return [...(c.need !== null ? [c.need] : []), c.policyCap, c.mandateCap, c.freeFunds].reduce((a, b) => (b < a ? b : a));
}

export function createForkedPolicyEngine(v: Vendored) {
  const { ProofEscrowAbi, QEDLensAbi, QEDVaultAbi, QEDExecutionAbi } = v.abi;
  const { mandateHash, signCertificate } = v.eip712;
  const { canonical, hashRecord, invoiceDigest } = v.records;
  const POLICY = v.economics.POLICY;
  const { solve } = v.execution;
  const { hashOrder, readVenues } = v.trader;
  const { decideTranche, impactBps, observeTreasury, policyMessage } = v.treasury;
  const { certificateNow } = v.clock;
  const { TRADE_POLICY, ownerInstructionMessage, ownerTradeMessage } = v.cosigner;
  void POLICY;

  class ForkedPolicyEngine {
    private seenInvoices = new Set<string>();
    private seenNonces = new Set<string>();
    private chain: Chain$;
    private key: LocalAccount;
    private cfg: ForkCosignerConfig;
    constructor(chain: Chain$, key: LocalAccount, cfg: ForkCosignerConfig) {
      this.chain = chain;
      this.key = key;
      this.cfg = cfg;
      if (cfg.authority === "d7" && !cfg.d7) throw new Error('authority "d7" needs its configuration (d7): the co-signer was not started');
      mkdirSync(cfg.recordsDir, { recursive: true });
    }

    get address() {
      return this.key.address;
    }

    async evaluate(req: CertRequest): Promise<CertResponse> {
      const pub = this.chain.pub;
      await this.loadUnits();
      const block = await pub.getBlock();
      const now = certificateNow(Number(block.timestamp), this.chain.chainId);
      const snap = (await pub.readContract({ address: this.cfg.lens, abi: QEDLensAbi, functionName: "snapshot", args: [this.cfg.vault] })) as any;
      const mHash = mandateHash(req.mandate);
      const checks: Check[] = [];
      const add = (id: string, name: string, pass: boolean, detail: string) => checks.push({ id, name, pass, detail });

      // C1–C3: authority (re-verified independently of the agent and of the vault)
      const digest = (await pub.readContract({ address: this.cfg.lens, abi: QEDLensAbi, functionName: "mandateDigest", args: [this.cfg.vault, req.mandate as any] } as any)) as Hex;
      const signer = await this.ownerSigned(snap.owner, digest, req.ownerSig, "recovered");
      add("C1", "Mandate signed by the vault owner", signer.ok, signer.detail);
      add("C2", "Mandate active and current epoch", now >= Number(req.mandate.validFrom) && now <= Number(req.mandate.validUntil) && BigInt(snap.epoch) === req.mandate.epoch, `epoch ${snap.epoch}, valid until ${new Date(Number(req.mandate.validUntil) * 1000).toISOString()}`);

      let payee: Address;
      let amount: bigint;
      let dueAt = 0n;
      let ref: Hex;
      let intentId: Hex;
      let summary: Record<string, unknown>;

      if (req.kind === "purchase") {
        const inv = req.invoice;
        payee = getAddress(inv.payTo);
        amount = BigInt(inv.amount);
        ref = keccak256(toHex(inv.invoiceId));
        intentId = keccak256(toHex(`purchase:${inv.invoiceId}:${req.jobId}`));
        summary = { kind: "purchase", invoice: inv, jobId: req.jobId, rationale: req.rationale, brainEngine: req.brainEngine };

        // C3–C6: counterparty authentication, invoice integrity, price sanity, replay
        const expectedSigner = this.cfg.vendorKeys[payee.toLowerCase()];
        const invSigner = await recoverMessageAddress({ message: { raw: invoiceDigest(inv) }, signature: req.vendorSig }).catch(() => "0x0" as Address);
        add("C3", "Invoice signed by the payee's registered key", !!expectedSigner && getAddress(invSigner) === getAddress(expectedSigner), `invoice signer ${invSigner}`);
        add("C4", "Invoice addressed to this vault, not expired", getAddress(inv.buyer) === getAddress(this.cfg.vault) && now <= inv.expiresAt, `buyer ${inv.buyer}, expires ${new Date(inv.expiresAt * 1000).toISOString()}`);
        const listPrice = this.cfg.catalogPrices[inv.productId];
        add("C5", "Price equals the vendor's published list price", listPrice !== undefined && amount <= listPrice, `invoice ${this.fmt(amount)} vs list ${listPrice !== undefined ? this.fmt(listPrice) : "n/a"}`);
        add("C6", "Invoice not seen before", !this.seenInvoices.has(inv.invoiceId), inv.invoiceId);

        // C7–C8: economic justification — spend only to earn, on data the job actually needs
        const job = (await pub.readContract({ address: this.cfg.escrow, abi: ProofEscrowAbi, functionName: "getJob", args: [BigInt(req.jobId)] })) as any;
        const jobOk = Number(job.status) === 1 && getAddress(job.payee) === getAddress(this.cfg.vault);
        add("C7", "Funded escrow job exists for this vault and covers the cost with margin", jobOk && BigInt(job.price) * BigInt(10_000 - POLICY.minMarginBps) / 10_000n >= amount, `job #${req.jobId}: status ${job.status}, price ${this.fmt(BigInt(job.price ?? 0))}, cost ${this.fmt(amount)}`);
        add("C8", "Purchased data is exactly what the job's committed spec requires", jobOk && job.specHash === inv.dataCommitment, `job spec ${job.specHash?.slice(0, 10)}… vs data ${inv.dataCommitment.slice(0, 10)}…`);
      } else {
        payee = getAddress(req.payee);
        amount = req.amount;
        ref = keccak256(toHex(`owner-instruction:${req.nonce}`));
        intentId = keccak256(toHex(`owner:${req.nonce}`));
        dueAt = req.dueInDays ? BigInt(now + req.dueInDays * 86_400) : 0n;
        summary = { kind: "owner-instructed", instruction: req.instruction, payee, amount, dueInDays: req.dueInDays ?? 0, nonce: req.nonce };
        const msg = ownerInstructionMessage(this.cfg.vault, payee, amount, req.dueInDays, req.nonce);
        const s = await this.ownerSignedMessage(snap.owner, msg, req.instructionSig, "instruction signer");
        add("C3", "Instruction confirmed by the owner's signature", s.ok, s.detail);
        add("C6", "Instruction nonce not seen before", !this.seenNonces.has(req.nonce), req.nonce);
      }

      // C9–C12: scope, solvency, screening, earned autonomy
      add("C9", "Payee is listed in the owner's mandate", req.mandate.payees.some((p) => getAddress(p) === payee), payee);
      const free = BigInt(snap.freeBalance);
      add("C10", "Reserve buffer above ring-fenced liabilities preserved", free - amount >= this.reserveBuffer, `free ${this.fmt(free)} − ${this.fmt(amount)} = ${this.fmt(free - amount)} ≥ ${this.fmt(this.reserveBuffer)} (ring-fenced ${this.fmt(BigInt(snap.protectedBalance))})`);
      add("C11", "Sanctions / deny-list screening", !this.cfg.denylist.some((d) => getAddress(d) === payee), "payee not on deny-list");
      let authorityHold: { cost: bigint; kind: Reservation["kind"] } | null = null;
      if (this.authorityRule === "d7") {
        // R7 decision D7: C12 is the authority budget (rail/authority-ledger.ts), not the release's earned allowance
        const c12 = await this.authorityForPayment(snap, payee, amount, dueAt > 0n, now);
        authorityHold = c12.hold;
        add("C12", c12.name, c12.pass, c12.detail);
      } else {
        const { revenue, spent } = await this.trackRecord();
        const allowance = this.earnedBase + revenue / 2n;
        add("C12", "Earned autonomy: discretionary spend ≤ 10 + 50% of VERIFIED revenue", spent + amount <= allowance, `spent ${this.fmt(spent)} + ${this.fmt(amount)} ≤ allowance ${this.fmt(allowance)} (verified revenue ${this.fmt(revenue)})`);
      }

      const approved = checks.every((c) => c.pass);
      const core = {
        schema: "qed.decision-record/v1",
        cosigner: this.key.address,
        chainId: this.chain.chainId,
        vault: this.cfg.vault,
        block: { number: block.number, timestamp: now },
        mandateHash: mHash,
        request: summary,
        payment: { payee, amount, dueAt, intentId, ref },
        treasury: { balance: snap.balance, protected: snap.protectedBalance, free: snap.freeBalance, spentInWindow: snap.spentInWindow, dailyCap: snap.dailyCap, blastRadius24h: snap.blastRadius24h },
        checks,
        verdict: approved ? "APPROVED" : "REFUSED",
      };
      const evidenceHash = hashRecord(core);
      const reasons = checks.filter((c) => !c.pass).map((c) => `${c.id} ${c.name}: ${c.detail}`);
      let certificate: Certificate | undefined;
      let signature: Hex | undefined;
      if (approved) {
        certificate = {
          mandateHash: mHash,
          recipient: payee,
          amount,
          dueAt,
          intentId,
          evidenceHash,
          ref,
          notBefore: BigInt(now - 60),
          expiresAt: BigInt(now + 2 * 3600),
          epoch: req.mandate.epoch,
        };
        signature = await signCertificate(this.key, this.chain.chainId, this.cfg.vault, certificate);
        if (req.kind === "purchase") this.seenInvoices.add(req.invoice.invoiceId);
        else this.seenNonces.add(req.nonce);
        if (authorityHold) this.reserveAuthority(certificate, authorityHold);
      }
      const recordPath = `${this.cfg.recordsDir}/${evidenceHash}.json`;
      writeFileSync(recordPath, JSON.stringify({ core: JSON.parse(canonical(core)), canonical: canonical(core), evidenceHash, certificate: certificate ? JSON.parse(canonical(certificate)) : null, signature: signature ?? null }, null, 2));
      return { approved, certificate, signature, evidenceHash, recordPath, checks, reasons };
    }

    /**
     * Reviews a conversion. The co-signer does not trust the agent's plan: it reads the venues itself,
     * solves the routing problem itself, and writes ITS quote (less the slippage allowance) into the
     * order as the floor. The route and the proof stay the agent's job; the chain checks them.
     */
    async evaluateTrade(req: TradeRequest): Promise<TradeResponse> {
      const pub = this.chain.pub;
      await this.loadUnits();
      const block = await pub.getBlock();
      const now = certificateNow(Number(block.timestamp), this.chain.chainId);
      const snap = (await pub.readContract({ address: this.cfg.lens, abi: QEDLensAbi, functionName: "snapshot", args: [this.cfg.vault] })) as any;
      const mHash = mandateHash(req.mandate);
      const checks: Check[] = [];
      const add = (id: string, name: string, pass: boolean, detail: string) => checks.push({ id, name, pass, detail });
      const digest = (await pub.readContract({ address: this.cfg.lens, abi: QEDLensAbi, functionName: "mandateDigest", args: [this.cfg.vault, req.mandate as any] } as any)) as Hex;
      const signer = await this.ownerSigned(snap.owner, digest, req.ownerSig, "recovered");
      add("C1", "Mandate signed by the vault owner", signer.ok, signer.detail);
      add("C2", "Mandate active and current epoch", now >= Number(req.mandate.validFrom) && now <= Number(req.mandate.validUntil) && BigInt(snap.epoch) === req.mandate.epoch, `epoch ${snap.epoch}`);
      let policyCheck: { amountIn: bigint; reason: string } | undefined;
      if (req.policy) {
        const p = req.policy;
        const s = await this.ownerSignedMessage(snap.owner, policyMessage(p), req.policySig ?? "0x", "policy signer");
        const fits = getAddress(p.vault) === getAddress(this.cfg.vault) && getAddress(p.reserve) === getAddress(req.recipient) && getAddress(p.tokenIn) === getAddress(req.tokenIn) && getAddress(p.tokenOut) === getAddress(req.tokenOut);
        add("C3", "Standing treasury policy signed by the owner, current, and covering this conversion", s.ok && BigInt(now) <= p.validUntil && fits, `${s.detail}, valid until ${new Date(Number(p.validUntil) * 1000).toISOString()}`);
        // P1–P2: the co-signer re-derives the agent's decision from the chain and the policy, and allows no more
        const view = await observeTreasury(pub, p, req.module, this.reserveBuffer);
        const own = decideTranche(view.venues, p, view.reserveFree, view.available, req.mandate.maxPerPayment);
        policyCheck = { amountIn: own.amountIn, reason: own.reason };
        add("P1", "Independent decision under the policy: a shortfall exists and a tranche is due", own.action === "convert", `reserve free ${view.reserveFree} vs target ${p.targetFree}; ${own.reason}`);
        // D-K4a: P2 asks only what P1 does not, and leaves the cost limit to P3
        const due = own.action === "convert", sized = policyTranche(own.candidates);
        add("P2", "If a tranche is due, the request is no larger than the tranche the policy allows and no smaller than its smallest", !due || (req.amountIn <= sized && req.amountIn >= p.minTranche), due ? `requested ${req.amountIn} ≤ allowed ${sized} (the shortfall's tranche ${own.candidates.need ?? "beyond the caps"}, policy cap ${own.candidates.policyCap}, mandate cap ${own.candidates.mandateCap}, free funds ${own.candidates.freeFunds}) and ≥ the smallest ${p.minTranche}; the cost is P3's` : "no tranche is due (P1), so there is no tranche to compare the request with");
        const ib = impactBps(view.venues, req.tokenIn, req.tokenOut, req.amountIn);
        add("P3", "Execution cost within the policy's impact limit", ib <= p.maxImpactBps, `${ib.toFixed(1)} bps ≤ ${p.maxImpactBps} bps`);
      } else {
        const msg = ownerTradeMessage(this.cfg.vault, req.amountIn, req.tokenIn, req.tokenOut, req.recipient, req.nonce);
        const s = await this.ownerSignedMessage(snap.owner, msg, req.instructionSig ?? "0x", "instruction signer");
        add("C3", "Conversion confirmed by the owner's signature", s.ok, s.detail);
      }
      add("C6", "Instruction nonce not seen before", !this.seenNonces.has(req.nonce), req.nonce);
      add("C9", "Recipient is listed in the owner's mandate", req.mandate.payees.some((p) => getAddress(p) === getAddress(req.recipient)), req.recipient);
      add("C9b", "Execution module is the vault's agent and a mandate payee", getAddress(snap.agent) === getAddress(req.module) && req.mandate.payees.some((p) => getAddress(p) === getAddress(req.module)), `agent ${snap.agent}`);
      const free = BigInt(snap.freeBalance);
      add("C10", "Reserve buffer above ring-fenced liabilities preserved", free - req.amountIn >= this.reserveBuffer, `free ${this.fmt(free)} − ${this.fmt(req.amountIn)} = ${this.fmt(free - req.amountIn)} ≥ ${this.fmt(this.reserveBuffer)}`);
      add("C11", "Sanctions / deny-list screening", !this.cfg.denylist.some((d) => getAddress(d) === getAddress(req.recipient)), "recipient not on deny-list");

      // T1–T3: an independent quote, a manipulation screen, and the venue set the proof must range over
      const venues = await readVenues(pub, req.module);
      const venueSetHash = (await pub.readContract({ address: req.module, abi: QEDExecutionAbi, functionName: "venueSetHash" })) as Hex;
      const own = solve(venues, req.tokenIn, req.tokenOut, req.amountIn);
      add("T1", "Independent re-quote: own optimal route executes", own.sim.ok && own.sim.amountOut > 0n, `own route ${own.route.length} hops → ${own.sim.amountOut} (bound ${own.bound}, gap ${own.gapPpm.toFixed(3)} ppm)`);
      // T2: the quoted rate must sit close to the depth-weighted mid price of the direct venues — a screen
      // against venues pushed off-market before signing (it cannot see a manipulation of every venue at once).
      const direct = venues.filter((v) => [v.token0, v.token1].map((x) => x.toLowerCase()).sort().join() === [req.tokenIn, req.tokenOut].map((x) => x.toLowerCase()).sort().join());
      const depth = (v: (typeof venues)[number]) => Number(v.token0.toLowerCase() === req.tokenIn.toLowerCase() ? v.r0 : v.r1);
      const mid = (v: (typeof venues)[number]) => (v.token0.toLowerCase() === req.tokenIn.toLowerCase() ? Number(v.r1) / Number(v.r0) : Number(v.r0) / Number(v.r1));
      const wMid = direct.reduce((a, v) => a + mid(v) * depth(v), 0) / Math.max(1, direct.reduce((a, v) => a + depth(v), 0));
      const rate = Number(own.sim.amountOut) / Number(req.amountIn);
      const deviation = wMid > 0 ? Math.abs(rate / wMid - 1) * 10_000 : Infinity;
      // D-K4a: computed only when T1 passes: without a route that executes there is no quoted rate to screen, and T1 says so
      if (own.sim.ok && own.sim.amountOut > 0n) add("T2", "Quoted rate close to the venues' depth-weighted mid (manipulation screen)", deviation <= TRADE_POLICY.maxRateDeviationBps, `rate ${rate.toFixed(6)} vs weighted mid ${wMid.toFixed(6)}: ${deviation.toFixed(1)} bps (limit ${TRADE_POLICY.maxRateDeviationBps})`);
      // D-K4a: the venue set the order commits to is the one read and solved over: QEDExecution's keccak256(abi.encode(venues))
      const solvedOver = venueSetHashOf(venues);
      add("T3", "Order commits to the venue set the co-signer read and solved over", solvedOver.toLowerCase() === String(venueSetHash).toLowerCase(), `the ${venues.length} venues read hash to ${solvedOver}; the module commits to ${venueSetHash}`);

      const order: Order = {
        tokenOut: getAddress(req.tokenOut),
        recipient: getAddress(req.recipient),
        minOut: (own.sim.amountOut * BigInt(10_000 - TRADE_POLICY.slippageBps)) / 10_000n,
        // τ: 1 ppm normally; on a dislocated market the honest route itself cannot get closer than its measured gap
        // (an arbitrage leg must be split in time), so τ follows twice that gap, capped.
        // S5 (change 6): with minToleranceUnits configured, τ never asks for less than that many base units of the output
        tolerancePpm: this.orderTolerance(Math.min(TRADE_POLICY.maxTolerancePpm, Math.max(TRADE_POLICY.tolerancePpm, Math.ceil(2 * own.gapPpm))), own.sim.amountOut),
        venueSetHash,
      };
      let authorityHold: { cost: bigint; kind: Reservation["kind"] } | null = null;
      if (this.authorityRule === "d7") {
        // R7 decision D7: the conversion's worst-case cost against the reference must fit in the authority budget
        const c12 = await this.authorityForTrade(snap, req, order, wMid, now);
        authorityHold = c12.hold;
        add("C12", c12.name, c12.pass, c12.detail);
      }
      const approved = checks.every((c) => c.pass);
      const intentId = keccak256(toHex(`trade:${req.nonce}`));
      const ref = hashOrder(order);
      const core = {
        schema: "qed.decision-record/v1",
        cosigner: this.key.address,
        chainId: this.chain.chainId,
        vault: this.cfg.vault,
        block: { number: block.number, timestamp: now },
        mandateHash: mHash,
        request: { kind: req.policy ? "policy-trade" : "trade", instruction: req.instruction, brainEngine: req.brainEngine, nonce: req.nonce, tokenIn: req.tokenIn, tokenOut: req.tokenOut, amountIn: req.amountIn, recipient: req.recipient, policy: req.policy ?? null, policyDecision: policyCheck ?? null },
        quote: { amountOut: own.sim.amountOut, bound: own.bound, gapPpm: own.gapPpm, route: own.route, nu: own.nu },
        order,
        payment: { payee: req.module, amount: req.amountIn, dueAt: 0n, intentId, ref },
        treasury: { balance: snap.balance, protected: snap.protectedBalance, free: snap.freeBalance, spentInWindow: snap.spentInWindow, dailyCap: snap.dailyCap, blastRadius24h: snap.blastRadius24h },
        checks,
        verdict: approved ? "APPROVED" : "REFUSED",
      };
      const evidenceHash = hashRecord(core);
      let certificate: Certificate | undefined;
      let signature: Hex | undefined;
      if (approved) {
        certificate = { mandateHash: mHash, recipient: getAddress(req.module), amount: req.amountIn, dueAt: 0n, intentId, evidenceHash, ref, notBefore: BigInt(now - 60), expiresAt: BigInt(now + (this.authorityRule === "d7" ? D7_CONVERSION_CERTIFICATE_SECONDS : 4 * 3600)), epoch: req.mandate.epoch };
        signature = await signCertificate(this.key, this.chain.chainId, this.cfg.vault, certificate);
        this.seenNonces.add(req.nonce);
        if (authorityHold) this.reserveAuthority(certificate, authorityHold);
      }
      const recordPath = `${this.cfg.recordsDir}/${evidenceHash}.json`;
      writeFileSync(recordPath, JSON.stringify({ core: JSON.parse(canonical(core)), canonical: canonical(core), evidenceHash, certificate: certificate ? JSON.parse(canonical(certificate)) : null, signature: signature ?? null }, null, 2));
      return { approved, certificate, signature, evidenceHash, recordPath, checks, reasons: checks.filter((c) => !c.pass).map((c) => `${c.id} ${c.name}: ${c.detail}`), order, quote: { amountOut: own.sim.amountOut, bound: own.bound, route: own.route } };
    }

    /** Verified revenue = escrow settlements INTO the vault; spend = agent payments OUT of it. */
    private async trackRecord(): Promise<{ revenue: bigint; spent: bigint }> {
      const pub = this.chain.pub;
      const settled = await pub.getContractEvents({ address: this.cfg.escrow, abi: ProofEscrowAbi, eventName: "JobSettled", fromBlock: this.cfg.deployBlock });
      const paid = await pub.getContractEvents({ address: this.cfg.vault, abi: QEDVaultAbi, eventName: "PaymentExecuted", fromBlock: this.cfg.deployBlock });
      let revenue = 0n;
      for (const e of settled as any[]) if (getAddress(e.args.payee) === getAddress(this.cfg.vault)) revenue += BigInt(e.args.price);
      let spent = 0n;
      for (const e of paid as any[]) spent += BigInt(e.args.amount);
      return { revenue, spent };
    }

    // ───────────── added by the fork (S5, change 6) ─────────────
    /**
     * τ for an order: the release's, raised so that it never asks for less than cfg.minToleranceUnits base units of the
     * output token (the bound rounds up and each hop's output down), and never above QEDExecution's MAX_TOLERANCE_PPM (1%).
     * Without the setting, exactly the release's.
     */
    private orderTolerance(release: number, out: bigint): number {
      const units = this.cfg.minToleranceUnits;
      if (!units || out <= 0n) return release;
      const floor = Number((BigInt(units) * 1_000_000n + out - 1n) / out);
      return Math.min(10_000, Math.max(release, floor));
    }

    // ───────────── added by the fork (D-A) ─────────────
    private decimals: number | null = null;
    private reserveBuffer = 0n;
    private earnedBase = 0n;
    /** The release's figures in its units (5 and 10 tUSD), in the units of this vault's asset. */
    private async loadUnits(): Promise<void> {
      if (this.decimals !== null) return;
      const asset = (await this.chain.pub.readContract({ address: this.cfg.vault, abi: VAULT_ASSET_ABI, functionName: "asset" })) as Address;
      const d = Number(await this.chain.pub.readContract({ address: asset, abi: ERC20_DECIMALS_ABI, functionName: "decimals" }));
      this.decimals = d;
      this.reserveBuffer = 5n * 10n ** BigInt(d);
      this.earnedBase = 10n * 10n ** BigInt(d);
    }
    private fmt(x: bigint): string {
      return (Number(x) / 10 ** (this.decimals ?? 6)).toFixed(2);
    }
    /** OpenZeppelin SignatureChecker, as QEDVault uses it: ECDSA for an owner without code, ERC-1271 otherwise. */
    private async ownerSigned(owner: Address, hash: Hex, signature: Hex, label: string): Promise<{ ok: boolean; detail: string }> {
      const code = await this.chain.pub.getCode({ address: owner });
      if (!code || code === "0x") {
        const signer = await recoverAddress({ hash, signature }).catch(() => "0x0" as Address);
        return { ok: getAddress(signer) === getAddress(owner), detail: `${label} ${signer}` };
      }
      const magic = await this.chain.pub.readContract({ address: owner, abi: ERC1271_ABI, functionName: "isValidSignature", args: [hash, signature] }).catch(() => "0x00000000");
      return { ok: String(magic).toLowerCase() === "0x1626ba7e", detail: `ERC-1271 owner account ${getAddress(owner)} answered ${String(magic)}` };
    }
    private async ownerSignedMessage(owner: Address, message: string, signature: Hex, label: string): Promise<{ ok: boolean; detail: string }> {
      const code = await this.chain.pub.getCode({ address: owner });
      if (!code || code === "0x") {
        const s = await recoverMessageAddress({ message, signature }).catch(() => "0x0" as Address);
        return { ok: getAddress(s) === getAddress(owner), detail: `${label} ${s}` };
      }
      return this.ownerSigned(owner, hashMessage(message), signature, label);
    }

    // ───────────── added by the fork (R7 decision D7; only with authority "d7") ─────────────
    /** Grants and reservations live in the co-signer's durable state (rail/cosigner.ts), which hands them over after each configure. */
    private authorityGrants: () => Grant[] = () => [];
    private authorityHeld: Reservation[] = [];
    /** D-K1b: the owner's signed earned-authority caps in force at a moment (ms), from the co-signer's durable state. */
    private authorityCaps: (nowMs: number) => { perWindow: string | null; perPayer: string | null } = () => ({ perWindow: null, perPayer: null });
    private get authorityRule(): "release" | "d7" {
      return this.cfg.authority === "d7" ? "d7" : "release";
    }
    private d7(): D7Config {
      if (!this.cfg.d7) throw new Error('authority "d7" needs its configuration (d7): nothing was decided');
      return this.cfg.d7;
    }
    setAuthorityState(grants: () => Grant[], reservations: Reservation[], caps?: (nowMs: number) => { perWindow: string | null; perPayer: string | null }): void {
      this.authorityGrants = grants;
      this.authorityHeld = [...reservations];
      if (caps) this.authorityCaps = caps;
    }
    authorityReservations(): Reservation[] {
      return [...this.authorityHeld];
    }
    /**
     * The budget from the chain's history, the owner's grants and the certificates still outstanding. It forgets the
     * reservations that no longer reserve (used, expired, voided) by removing exactly those: one added by a certificate
     * signed while the chain was being read is never dropped.
     */
    private async authorityLedger(epoch: bigint, now: number): Promise<Ledger> {
      // D-K1b: K1's caps are the operator's, lowered by the owner's signed caps in force now (never raised by them)
      const d = withOwnerCaps(this.d7(), this.authorityCaps(now * 1000)), seen = [...this.authorityHeld];
      const { logs, latestBlock } = await readAuthorityLogs(this.chain.pub, d, { vault: QEDVaultAbi, execution: QEDExecutionAbi, escrow: ProofEscrowAbi }, this.cfg.deployBlock);
      const l = buildLedger(d, eventsFromLogs(d, logs), { latestBlock, grants: this.authorityGrants(), reservations: seen, now: BigInt(now), epoch });
      const gone = new Set(seen.filter((r) => !l.liveReservations.includes(r)));
      this.authorityHeld = this.authorityHeld.filter((r) => !gone.has(r));
      return l;
    }
    /** The budget as a read, for the rail's payment preview: nothing is signed or reserved. */
    async authorityView(): Promise<AuthorityView> {
      await this.loadUnits();
      const pub = this.chain.pub;
      const block = await pub.getBlock();
      const now = certificateNow(Number(block.timestamp), this.chain.chainId);
      const snap = (await pub.readContract({ address: this.cfg.lens, abi: QEDLensAbi, functionName: "snapshot", args: [this.cfg.vault] })) as any;
      return viewOf(this.d7(), await this.authorityLedger(BigInt(snap.epoch), now));
    }
    private reserveAuthority(certificate: Certificate, hold: { cost: bigint; kind: Reservation["kind"] }): void {
      this.authorityHeld.push({ intentId: certificate.intentId, cost: hold.cost.toString(), kind: hold.kind, expiresAt: certificate.expiresAt.toString(), epoch: certificate.epoch.toString(), at: new Date().toISOString() });
    }
    /** C12 of an owner-instructed payment: what it takes out of the workspace's control must fit in what is available. */
    private async authorityForPayment(snap: any, payee: Address, amount: bigint, forward: boolean, now: number) {
      const d = this.d7(), S = d.symbol, u = (x: bigint) => units(x, d.decimals);
      const l = await this.authorityLedger(BigInt(snap.epoch), now);
      const { cost, how } = paymentCost(d, payee, amount, forward);
      const what = how === "self-payment"
        ? `${u(amount)} ${S} to ${payee}, an account of the workspace itself: nothing leaves its control, so it uses nothing`
        : how === "hold"
          ? `a promise of ${u(amount)} ${S} to ${payee}: set aside from now until it is paid or released, so it needs ${u(cost)} ${S} available`
          : `${u(amount)} ${S} to ${payee}, outside the workspace: it uses ${u(cost)} ${S}`;
      const kind: Reservation["kind"] = forward ? "hold" : "payment";
      return { name: "Authority budget (R7 D7): what this payment takes out of the workspace's control fits in what the owner granted and the workspace earned", pass: cost <= l.available, detail: `${what}; ${viewOf(d, l).statement}`, hold: cost > 0n ? { cost, kind } : null };
    }
    /** C12 of a conversion: its worst case against the reference (the order's floor at the band's low end) must fit in what is available. */
    private async authorityForTrade(snap: any, req: TradeRequest, order: Order, marketOutPerIn: number, now: number) {
      const d = this.d7(), S = d.symbol, u = (x: bigint) => units(x, d.decimals);
      const l = await this.authorityLedger(BigInt(snap.epoch), now);
      const c = conversionCost(d, { tokenIn: req.tokenIn, amountIn: req.amountIn, tokenOut: req.tokenOut, minOut: order.minOut, recipient: req.recipient, marketOutPerIn });
      const name = "Authority budget (R7 D7): this conversion's cost against the reference fits in what the owner granted and the workspace earned";
      const statement = viewOf(d, l).statement;
      const kind: Reservation["kind"] = "conversion";
      const hold = c.cost > 0n ? { cost: c.cost, kind } : null;
      if (c.how === "convert-and-pay") return { name, pass: c.cost <= l.available, detail: `the output goes to ${req.recipient}, outside the workspace, so the conversion is a payment of its input: it uses ${u(c.cost)} ${S}; ${statement}`, hold };
      if (c.how === "unvalued-input") return { name, pass: false, detail: `${req.tokenIn} has no reference band, so what this conversion gives cannot be valued at the top of one: it is refused; ${statement}`, hold: null };
      if (c.how === "unvalued" || !c.ref) return { name, pass: c.cost <= l.available, detail: `${req.tokenOut} has no reference band, so what the conversion receives is worth nothing to the budget and it uses its whole input, ${u(c.cost)} ${S}; ${statement}`, hold };
      const r = c.ref, b = bandOf(d, req.tokenOut).band, R = r.symbol;
      const ref = `the reference band ${price(b.lo, r, d)} to ${price(b.hi, r, d)} ${S} per ${R} (${r.source})`;
      const mid = c.market === null ? "no direct venue" : `${(c.market * 10 ** (r.decimals - d.decimals)).toFixed(2)} ${S} per ${R}`;
      if (!c.inside) return { name, pass: false, detail: `the venues' depth-weighted mid is ${mid}, outside ${ref}${r.divergenceBps ? ` widened by ${r.divergenceBps / 100}%` : ""}: the reference does not describe the market now, so the conversion cannot be valued and is refused; ${statement}`, hold: null };
      return { name, pass: c.cost <= l.available, detail: `${u(req.amountIn)} ${S} into ${R} for ${req.recipient}, an account of the workspace, uses only its cost against the reference: what is given less what is received, valued at the band's low end. At the order's floor of ${units(order.minOut, r.decimals)} ${R} and ${price(b.lo, r, d)} ${S} per ${R} (${ref}; the venues' mid now ${mid}) it can cost at most ${u(c.cost)} ${S}, reserved until the conversion executes, when its realised cost is counted instead; ${statement}`, hold };
    }
  }

  return ForkedPolicyEngine;
}
export type ForkedPolicyEngine = InstanceType<ReturnType<typeof createForkedPolicyEngine>>;
